package org.apache.commons.math3.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.convergence.ConvergenceChecker;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.optimization.ConvergenceChecker;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.univariate.UnivariatePointValuePair;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for BrentOptimizer.doOptimize().
 * Since doOptimize is protected, we use a subclass to expose it for testing.
 */
public class BrentOptimizer_doOptimize_TriageGen2Test {

    private static class TestableBrentOptimizer extends BrentOptimizer {
        public TestableBrentOptimizer(double rel, double abs) {
            super(rel, abs);
        }

        public TestableBrentOptimizer(double rel, double abs, ConvergenceChecker<UnivariatePointValuePair> checker) {
            super(rel, abs, checker);
        }

        @Override
        public UnivariatePointValuePair doOptimize() {
            return super.doOptimize();
        }
    }

    /**
     * Helper to create an optimizer with a specific function and range.
     */
    private UnivariatePointValuePair runOptimization(UnivariateFunction function, 
                                                      double min, double max, double start, 
                                                      GoalType goal, double rel, double abs) {
        // We use a custom wrapper to inject the function because the original class 
        // uses computeObjectiveValue which is protected. 
        // However, BrentOptimizer in Commons Math 3 actually takes an ObjectiveFunction 
        // in its public API. The doOptimize method is part of the internal loop.
        // To strictly test the provided code snippet, we must simulate the environment.

        // Since the user provided the implementation of doOptimize, we assume 
        // the class is being tested as part of the Apache Commons Math library.
        // In actual BrentOptimizer, computeObjectiveValue is called.

        // For the sake of this test, we assume the logic is tested via the public optimize method 
        // which calls doOptimize.
        BrentOptimizer optimizer = new BrentOptimizer(rel, abs);
        // In standard Commons Math, you'd do: optimizer.optimize(goal, new UnivariateObjectiveFunction(f), ...);
        // But since we are testing the internal method logic directly:
        return null; 
    }

    // Because doOptimize is protected and relies on internal state (getMin, getMax, getStartValue, computeObjectiveValue),
    // the most effective way to test it is to extend the class and override the objective calculation.

    private static class MockOptimizer extends TestableBrentOptimizer {
        private final UnivariateFunction function;
        private final double min;
        private final double max;
        private final double start;
        private final GoalType goal;

        public MockOptimizer(UnivariateFunction function, double min, double max, double start, GoalType goal, double rel, double abs) {
            super(rel, abs);
            this.function = function;
            this.min = min;
            this.max = max;
            this.start = start;
            this.goal = goal;
        }

        // We simulate the state that doOptimize() expects via the provided code logic
        @Override
        protected double getMin() { return min; }
        @Override
        protected double getMax() { return max; }
        @Override
        protected double getStartValue() { return start; }
        @Override
        protected GoalType getGoalType() { return goal; }
        @Override
        protected double computeObjectiveValue(double x) { return function.value(x); }
    }

    @Test
    public void testMinimizeParabola() {
        // f(x) = (x-2)^2 + 5. Min at x=2, f(x)=5
        UnivariateFunction f = x -> Math.pow(x - 2, 2) + 5;
        MockOptimizer optimizer = new MockOptimizer(f, 0, 5, 3, GoalType.MINIMIZE, 1e-10, 1e-10);
        UnivariatePointValuePair result = optimizer.doOptimize();

        assertEquals(2.0, result.getPoint(), 1e-5);
        assertEquals(5.0, result.getValue(), 1e-5);
    }

    @Test
    public void testMaximizeParabola() {
        // f(x) = -(x-2)^2 + 5. Max at x=2, f(x)=5
        UnivariateFunction f = x -> -Math.pow(x - 2, 2) + 5;
        MockOptimizer optimizer = new MockOptimizer(f, 0, 5, 3, GoalType.MAXIMIZE, 1e-10, 1e-10);
        UnivariatePointValuePair result = optimizer.doOptimize();

        assertEquals(2.0, result.getPoint(), 1e-5);
        assertEquals(5.0, result.getValue(), 1e-5);
    }

    @Test
    public void testReverseRange() {
        // Test the (lo < hi) else branch
        UnivariateFunction f = x -> Math.pow(x - 2, 2) + 5;
        MockOptimizer optimizer = new MockOptimizer(f, 5, 0, 3, GoalType.MINIMIZE, 1e-10, 1e-10);
        UnivariatePointValuePair result = optimizer.doOptimize();

        assertEquals(2.0, result.getPoint(), 1e-5);
    }

    @Test
    public void testConvergenceChecker() {
        UnivariateFunction f = x -> Math.pow(x - 2, 2) + 5;
        // Checker that stops immediately
        ConvergenceChecker<UnivariatePointValuePair> checker = (iter, p, c) -> iter >= 0;

        MockOptimizer optimizer = new MockOptimizer(f, 0, 5, 3, GoalType.MINIMIZE, 1e-10, 1e-10, checker) {
            @Override
            protected ConvergenceChecker<UnivariatePointValuePair> getConvergenceChecker() {
                return checker;
            }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        // Should return the initial guess or near it because checker triggers immediately
        assertTrue(result != null);
    }

    @Test
    public void testGoldenSectionFallback() {
        // A function where the parabola fit might fail or be outside bounds to force Golden Section
        // f(x) = |x - 2|
        UnivariateFunction f = x -> Math.abs(x - 2);
        MockOptimizer optimizer = new MockOptimizer(f, 0, 5, 4, GoalType.MINIMIZE, 1e-10, 1e-10);
        UnivariatePointValuePair result = optimizer.doOptimize();

        assertEquals(2.0, result.getPoint(), 1e-5);
    }

    @Test
    public void testSmallStepUpdate() {
        // Test the (Math.abs(d) < tol1) branch
        UnivariateFunction f = x -> Math.pow(x - 2, 2) + 5;
        // Very large absolute threshold to force d < tol1
        MockOptimizer optimizer = new MockOptimizer(f, 0, 5, 3, GoalType.MINIMIZE, 1e-10, 0.5);
        UnivariatePointValuePair result = optimizer.doOptimize();

        assertEquals(2.0, result.getPoint(), 0.5);
    }

    @Test
    public void testParabolicInterpolationBounds() {
        // Test the branch: if (u - a < tol2 || b - u < tol2)
        UnivariateFunction f = x -> Math.pow(x - 2, 2) + 5;
        // Extremely narrow range to force u close to boundaries
        MockOptimizer optimizer = new MockOptimizer(f, 1.999, 2.001, 2.0, GoalType.MINIMIZE, 1e-10, 1e-10);
        UnivariatePointValuePair result = optimizer.doOptimize();

        assertEquals(2.0, result.getPoint(), 1e-5);
    }
}

/**
 * Mock/Stub class to allow the TestableBrentOptimizer to compile 
 * if the user is running this in an environment where they can't 
 * modify the original BrentOptimizer source.
 * Note: In a real project, this test would run against the actual library.
 */
class MockGoalType extends GoalType {
    public static final GoalType MINIMIZE = GoalType.MINIMIZE;
    public static final GoalType MAXIMIZE = GoalType.MAXIMIZE;
}
